CREATE EXTENSION IF NOT EXISTS pgcrypto; CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, branch_id uuid NOT NULL, barber_id uuid NOT NULL, service_id uuid NOT NULL, customer_id uuid, customer_name text NOT NULL, customer_contact text NOT NULL, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, occupied_start_at timestamptz NOT NULL, occupied_end_at timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('pending','confirmed','cancelled','completed','no_show')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(start_at<end_at),CHECK(occupied_start_at<occupied_end_at), UNIQUE(tenant_id,id));
ALTER TABLE public.appointments ADD CONSTRAINT appointments_no_overlap EXCLUDE USING gist (tenant_id WITH =, barber_id WITH =, tstzrange(occupied_start_at,occupied_end_at,'[)') WITH &&) WHERE (status IN ('pending','confirmed'));
CREATE INDEX appointments_tenant_barber_start_idx ON public.appointments(tenant_id,barber_id,start_at);
CREATE TABLE public.appointment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, appointment_id uuid NOT NULL, type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,appointment_id) REFERENCES public.appointments(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE public.idempotency_keys (tenant_id uuid NOT NULL, key text NOT NULL, fingerprint text NOT NULL, appointment_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,key));
CREATE TABLE public.outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, aggregate_id uuid NOT NULL, type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.appointments FORCE ROW LEVEL SECURITY; ALTER TABLE public.appointment_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.appointment_events FORCE ROW LEVEL SECURITY; ALTER TABLE public.idempotency_keys ENABLE ROW LEVEL SECURITY; ALTER TABLE public.idempotency_keys FORCE ROW LEVEL SECURITY; ALTER TABLE public.outbox_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.outbox_events FORCE ROW LEVEL SECURITY;
CREATE POLICY appointments_tenant ON public.appointments USING(current_user='appointment_db_owner' OR tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(current_user='appointment_db_owner' OR tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY appointment_events_tenant ON public.appointment_events USING(current_user='appointment_db_owner' OR tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(current_user='appointment_db_owner' OR tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY idempotency_tenant ON public.idempotency_keys USING(current_user='appointment_db_owner' OR tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(current_user='appointment_db_owner' OR tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY outbox_tenant ON public.outbox_events USING(current_user='appointment_db_owner' OR tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(current_user='appointment_db_owner' OR tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);
GRANT USAGE ON SCHEMA public TO appointment_db_app; GRANT SELECT,INSERT,UPDATE ON ALL TABLES IN SCHEMA public TO appointment_db_app;
